<?php namespace App\Http\Controllers; use App\Models\Lead; use App\Models\Campaign; use App\Models\FollowUp; class DashboardController extends Controller {public function __invoke(){$stats=['leads'=>Lead::count(),'qualified'=>Lead::whereIn('status',['qualified','proposal'])->count(),'customers'=>Lead::where('status','customer')->count(),'campaigns'=>Campaign::where('status','active')->count(),'followups'=>FollowUp::where('status','pending')->whereDate('due_at','<=',today())->count()];$recentLeads=Lead::with('campaign')->latest()->take(8)->get();$upcoming=FollowUp::with(['lead','assignee'])->where('status','pending')->orderBy('due_at')->take(6)->get();$pipeline=Lead::selectRaw('status,count(*) as total')->groupBy('status')->pluck('total','status');return view('dashboard',compact('stats','recentLeads','upcoming','pipeline'));}}